    // 启用状态以副本为准，否则卡刚启用的剧情条目回读仍是旧的禁用状态。
    var i;
    for (i = 0; i < WORLD_ENTRIES.length; i += 1) add(WORLD_ENTRIES[i], i);
    var table = charWorldEntries();
    for (i = 0; i < table.length; i += 1) add(table[i], i);
