      message_id: index,
      id: raw && raw.id ? String(raw.id) : '',
      name: String(raw && raw.name || (role === 'user' ? USER_NAME : CHAR_NAME)),
      is_user: role === 'user',
      is_system: role === 'system',
      mes: String(raw && raw.text != null ? raw.text : ''),
